function numOfWays(n) {
  const MOD = 1000000007;
  let twoColor = 6;
  let threeColor = 6;

  for (let row = 2; row <= n; row++) {
    const nextTwo = (3 * twoColor + 2 * threeColor) % MOD;
    const nextThree = (2 * twoColor + 2 * threeColor) % MOD;
    twoColor = nextTwo;
    threeColor = nextThree;
  }
  return (twoColor + threeColor) % MOD;
}

