function numOfWays(n) {
  const MOD = 1000000007;
  const patterns = [];
  for (let a = 0; a < 3; a++)
    for (let b = 0; b < 3; b++)
      for (let c = 0; c < 3; c++)
        if (a !== b && b !== c) patterns.push([a, b, c]);
  const fits = (p, q) => p[0] !== q[0] && p[1] !== q[1] && p[2] !== q[2];
  let ways = patterns.map(() => 1);
  for (let r = 1; r < n; r++) {
    ways = patterns.map((q) => {
      let total = 0;
      patterns.forEach((p, i) => { if (fits(p, q)) total = (total + ways[i]) % MOD; });
      return total;
    });
  }
  return ways.reduce((s, w) => (s + w) % MOD, 0);
}

